import { normalizeWords, joinWords } from './helper';

export default {
  id: 'words',
  name: 'Words',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'tool',
      tool: {
        name: 'normalize_words',
        version: '1.0.0',
        description: 'Normalize text into deduplicated, lowercased, sorted words joined by commas.',
        permissions: [],
        sideEffect: 'none',
        parameters: {
          type: 'object',
          properties: { text: { type: 'string', description: 'Input text with whitespace-separated words' } },
          required: ['text'],
          additionalProperties: false,
        },
        outputSchema: {
          type: 'object',
          properties: {
            result: { type: 'string' },
            words: { type: 'array', items: { type: 'string' } },
          },
          required: ['result', 'words'],
        },
        async handler(args: unknown, _tctx: unknown) {
          const { text } = args as { text: string };
          const words = normalizeWords(text);
          return { ok: true, data: { words, result: joinWords(words) } };
        },
      },
    });
  },
};

